
// Nine-hole answer garden. The animation clock also controls hit eligibility.
function moleArt(){return '<svg viewBox="0 0 180 125" aria-hidden="true"><ellipse cx="90" cy="119" rx="63" ry="57" fill="#985e3d"/><circle cx="39" cy="53" r="19" fill="#75452e"/><circle cx="141" cy="53" r="19" fill="#75452e"/><circle cx="39" cy="53" r="11" fill="#d69779"/><circle cx="141" cy="53" r="11" fill="#d69779"/><ellipse cx="90" cy="66" rx="61" ry="52" fill="#b57950"/><path d="M54 25 Q90 -3 125 25" fill="#c99168"/><ellipse cx="90" cy="83" rx="37" ry="27" fill="#e9bf8c"/><ellipse cx="67" cy="62" rx="7" ry="10" fill="#2d2537"/><ellipse cx="113" cy="62" rx="7" ry="10" fill="#2d2537"/><circle cx="69" cy="59" r="2" fill="white"/><circle cx="115" cy="59" r="2" fill="white"/><ellipse cx="90" cy="78" rx="13" ry="9" fill="#df8291"/><path d="M80 92 Q90 102 100 92" fill="none" stroke="#704831" stroke-width="3" stroke-linecap="round"/><path d="M86 96 v8 h9 v-8" fill="white"/><ellipse cx="32" cy="115" rx="20" ry="10" fill="#dba374"/><ellipse cx="148" cy="115" rx="20" ry="10" fill="#dba374"/></svg>';}
function initMoleRound(){const s=game.session;s.moleWave=0;s.moleClock=0;s.moleHit=null;s.molePaused ||= false;moleSpawn();}
function moleSpawn(){const s=game.session,old=s.moles||[],holes=shuffle(Array.from({length:9},(_,i)=>i)),order=shuffle(game.choices.map((_,i)=>i));s.moles=Array.from({length:9},()=>({choice:null,delay:0,lift:0,hittable:false}));order.forEach((choice,k)=>{let at=holes[k];if(old[at]?.choice===choice&&k<holes.length-1){[holes[k],holes[k+1]]=[holes[k+1],holes[k]];at=holes[k];}s.moles[at]={choice,delay:k*.3,lift:0,hittable:false};});s.moleWave++;s.moleClock=0;s.moleHold=Math.max(3.2,Math.min(7,Math.max(...game.choices.map(a=>a.length))/16));moleUpdate();}
function moleUpdate(){const s=game.session;for(const m of s.moles){const age=s.moleClock-m.delay,end=.45+s.moleHold;let lift=age<0?0:age<.45?age/.45:age<end?1:Math.max(0,1-(age-end)/.5);if(s.molePaused&&m.choice!==null)lift=1;if(typeof arcade!=='undefined'&&arcade.reduced)lift=lift>=.5?1:0;m.lift=m.choice===null?0:Math.max(0,Math.min(1,lift));m.hittable=s.phase==='question'&&m.choice!==null&&m.lift>=.85;}}
function moleSync(){const s=game.session;document.querySelectorAll('[data-mole-hole]').forEach(hole=>{const i=Number(hole.dataset.moleHole),m=s.moles[i],button=hole.querySelector('button'),label=button.querySelector('.mole-answer');const hit=s.moleHit?.hole===i;hole.classList.toggle('mole-bonk',hit);hole.classList.toggle('mole-up',m.hittable);const visibleLift=s.phase==='question'?m.lift:hit?1:0;button.style.setProperty('--mole-lift',visibleLift);button.disabled=!m.hittable;button.setAttribute('aria-hidden',String(visibleLift===0));button.setAttribute('aria-label',m.choice===null?'Empty hole '+(i+1):'Hole '+(i+1)+': '+game.choices[m.choice]);const answer=m.choice===null?'':game.choices[m.choice];if(label.textContent!==answer)label.textContent=answer;label.classList.toggle('mole-long',label.textContent.length>32);label.classList.toggle('mole-wordy',label.textContent.length>8);});}
function renderMole(){const s=game.session,feedback=s.phase==='feedback';$('.player-bottom>span').textContent='Tap a raised answer mole · keyboard 1–9';$('#arena').innerHTML='<section class="mole-game"><div class="mole-question"><span>QUESTION '+(s.round+1)+' / '+game.items.length+'</span><h2>'+esc(current().prompt)+'</h2></div><div class="mole-garden" role="group" aria-label="Nine answer holes">'+Array.from({length:9},(_,i)=>'<div class="mole-hole" data-mole-hole="'+i+'"><span class="mole-hole-shadow"></span><div class="mole-window"><button type="button" class="mole-button" data-mode-action="act-whack" data-value="'+i+'" disabled style="--mole-lift:0"><span class="mole-character">'+moleArt()+'</span><span class="mole-answer"></span></button></div><span class="mole-rim"></span><span class="mole-hole-number" aria-hidden="true">'+(i+1)+'</span>'+(s.moleHit?.hole===i?'<span class="mole-impact" aria-hidden="true">'+(s.moleHit.good?'⭐':'💫')+'</span>':'')+'</div>').join('')+'</div><div class="mole-footer">'+(feedback?'<div class="mole-response '+(game.feedbackGood?'mole-good':'mole-wrong')+'" role="status"><strong>'+(game.feedbackGood?'Great catch! +100':'Oops! The answer is '+esc(current().answer))+'</strong>'+ (current().explanation?'<span>'+esc(current().explanation)+'</span>':'')+'</div>'+actButton('next','Next question →'):'<p>Catch the correct answer as it pops up!</p>'+actButton('mole-pause',s.molePaused?'Resume popping ▶':'Freeze moles ❚❚','aria-pressed="'+s.molePaused+'"'))+'</div></section>';$('#arena').classList.add('activity-arena');moleUpdate();moleSync();document.querySelectorAll('.mole-button').forEach(button=>{button.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();handleMole(button);};button.onclick=e=>{if(e.detail>0){e.preventDefault();e.stopPropagation();}};});}
function handleMole(button){const s=game.session,a=button.dataset.modeAction,n=Number(button.dataset.value);if(game.done||ui.view!=='player'||button.disabled)return;if(a==='act-next'&&s.phase==='feedback'){actNext();renderGame();return;}if(s.phase!=='question')return;if(a==='act-mole-pause'){s.molePaused=!s.molePaused;if(!s.molePaused)s.moleClock=.45+Math.max(...s.moles.map(m=>m.delay));moleUpdate();renderGame();return;}if(a!=='act-whack'||!Number.isInteger(n)||!s.moles[n]?.hittable)return;const good=game.choices[s.moles[n].choice]===current().answer;s.moleHit={hole:n,good};s.moles.forEach(m=>m.hittable=false);actScore(good);renderGame();}
function stepMole(dt){const s=game.session;if(s.phase!=='question'||s.molePaused)return;s.moleClock+=dt;const duration=.45+s.moleHold+.5+.75+Math.max(...s.moles.map(m=>m.delay));if(s.moleClock>=duration)moleSpawn();else moleUpdate();moleSync();}
document.addEventListener('keydown',e=>{if(!game||game.lesson.format!=='mole'||ui.view!=='player'||game.done||e.repeat||e.target.closest('input,textarea,select,[contenteditable]'))return;if(/^[1-9]$/.test(e.key)){e.preventDefault();handleMole({dataset:{modeAction:'act-whack',value:String(Number(e.key)-1)}});}});
